INSERT INTO data_sources (source_key, name, agency, source_url, license_notes, refresh_cadence) VALUES
('bls_oews', 'Occupational Employment and Wage Statistics (OEWS)', 'U.S. Bureau of Labor Statistics', 'https://www.bls.gov/oes/tables.htm', 'Public domain U.S. government data. Wage estimates describe occupations in a labor market; they are not job offers or starting salaries. Some cells are suppressed (*, **) or top-coded (#).', 'Annual (May reference period, released the following spring)'),
('bls_ep', 'Employment Projections (education and training assignments, occupational projections)', 'U.S. Bureau of Labor Statistics', 'https://www.bls.gov/emp/tables.htm', 'Public domain. Typical entry-level education is a BLS assignment for the typical worker, not a legal requirement for every job.', 'Annual (10-year projection period)'),
('nces_cip_soc', 'CIP 2020 to SOC 2018 Crosswalk', 'National Center for Education Statistics', 'https://nces.ed.gov/ipeds/cipcode/resources.aspx', 'Public domain. Shows programs that prepare people for occupations. It is NOT a record of where graduates actually work.', 'Revised with each CIP/SOC taxonomy'),
('ed_scorecard', 'College Scorecard (institution and field-of-study data)', 'U.S. Department of Education', 'https://collegescorecard.ed.gov/data/', 'Public domain. Program earnings and debt describe qualifying former students and are often suppressed for small cohorts.', 'Periodic data releases'),
('hud_fmr', 'Fair Market Rents', 'U.S. Department of Housing and Urban Development', 'https://www.huduser.gov/portal/datasets/fmr.html', 'Public domain. FMRs are a policy benchmark (generally the 40th percentile gross rent for standard-quality units), not current listing prices or medians.', 'Annual (federal fiscal year)'),
('census_acs', 'American Community Survey 5-year estimates (table-based summary file)', 'U.S. Census Bureau', 'https://www.census.gov/programs-surveys/acs/data/summary-file.html', 'Public domain. Estimates carry margins of error and describe a 5-year period.', 'Annual'),
('irs_rev_proc', 'Rev. Proc. 2025-32 (2026 inflation adjustments incl. OBBBA amendments)', 'Internal Revenue Service', 'https://www.irs.gov/newsroom/irs-releases-tax-inflation-adjustments-for-tax-year-2026-including-amendments-from-the-one-big-beautiful-bill', 'Public domain. FuturePath uses a simplified estimator; not tax advice.', 'Annual'),
('ssa_wage_base', 'Social Security contribution and benefit base', 'Social Security Administration', 'https://www.ssa.gov/oact/cola/cbb.html', 'Public domain.', 'Annual'),
('ny_dtf', 'Form IT-2105-I (2026) New York State and New York City tax rate schedules', 'New York State Department of Taxation and Finance', 'https://www.tax.ny.gov/pdf/current_forms/it/it2105i.pdf', 'Public. Simplified: supplemental (recapture) tax for high incomes and credits are not modeled.', 'Annual'),
('dc_otr', 'DC individual income tax rates and standard deduction', 'DC Office of Tax and Revenue', 'https://otr.cfo.dc.gov/page/dc-individual-and-fiduciary-income-tax-rates', 'Public. Latest published standard deduction is for tax year 2025.', 'Annual'),
('va_tax', 'Virginia individual income tax rates and standard deduction', 'Virginia Department of Taxation', 'https://www.tax.virginia.gov/deductions', 'Public. Personal exemptions and credits are not modeled.', 'Annual'),
('fsa_rates', 'Federal Direct Loan interest rates (2026-27)', 'U.S. Department of Education, Federal Student Aid', 'https://studentaid.gov/understand-aid/types/loans/interest-rates', 'Public. Rates apply to loans first disbursed July 1, 2026 to June 30, 2027.', 'Annual (July 1)'),
('usda_food', 'USDA Food Plans: Cost of Food at Home (Low, Moderate, Liberal), U.S. average', 'U.S. Department of Agriculture, Food and Nutrition Service', 'https://www.fns.usda.gov/cnpp/usda-food-plans-cost-food-monthly-reports', 'Public. National averages, food prepared at home only. Not adjusted for local prices.', 'Monthly'),
('futurepath_assumption', 'FuturePath editable default assumption', 'FuturePath (not a government source)', 'https://127.0.0.1/docs/ASSUMPTIONS', 'Illustrative default chosen for teaching purposes where no locality-level public dataset is used. Always editable and labeled as an assumption.', 'Reviewed with each release'),
('state_no_wage_tax', 'States without a tax on wage income', 'State revenue departments', 'https://www.irs.gov/govt/state-links-1', 'Public. FL, TX, NV, WA, TN, SD, WY, AK and NH do not tax wage income.', 'As laws change'),
('bls_ooh', 'Occupational Outlook Handbook', 'U.S. Bureau of Labor Statistics', 'https://www.bls.gov/ooh/', 'Public domain. Linked for career descriptions and licensing context.', 'Annual');
